using System;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Asana.Core;
using Asana.Core.Authentication;
using Asana.Core.Exceptions;
using Asana.Core.Models;
using Asana.Core.Request;
using Asana.Core.Response;
using Asana.Errors;
using Asana.Models;
using Asana.Requests.Stories;

namespace Asana.Api;

/// <summary>
/// *See our forum post for more info on when conditional fields are returned.*
/// <para>
/// A story represents an activity associated with an object in the Asana system. Stories are generated by the system whenever users take actions such as creating or assigning tasks, or moving tasks between projects. "Comments" are also a form of user-generated story.
/// </para>
/// </summary>
public sealed class Stories
{
    private readonly RawClient _rawClient;
    private readonly Server _server;
    private readonly AuthSchemes _auth;

    internal Stories(RawClient rawClient, Server server, AuthSchemes auth)
    {
        _rawClient = rawClient;
        _server = server;
        _auth = auth;
    }

    /// <summary>
    /// Create a story on a task
    /// </summary>
    /// <param name="request">The operation's inputs</param>
    /// <param name="requestOptions">Per-request options, such as an overriding log level for this call</param>
    /// <param name="cancellationToken">Cancellation token</param>
    /// <returns>A <see cref="Task{TResult}"/> of <see cref="TasksStoriesResponse1"/> instance.</returns>
    /// <exception cref="ApiException{TError}"> of <see cref="CreateStoryForTaskError"/> when the server returns an error response.</exception>
    /// <remarks>
    /// Adds a story to a task. This endpoint currently only allows for comment
    /// stories to be created. The comment will be authored by the currently
    /// authenticated user, and timestamped when the server receives the request.
    /// <para>
    /// Returns the full record for the new story added to the task.
    /// </para>
    /// </remarks>
    public Task<TasksStoriesResponse1> CreateStoryForTask(CreateStoryForTaskRequest request,
        RequestOptions? requestOptions = null,
        CancellationToken cancellationToken = default) =>
        _rawClient.Execute(
            _server.Default("/tasks/{task_gid}/stories"),
            [new TemplateParam("task_gid", request.TaskGid)],
            [
                new Param("opt_pretty", request.OptPretty),
                new Param("opt_fields", request.OptFields, SerializationFormat.Csv),
            ],
            [new HeaderParam("Idempotency-Key", Guid.NewGuid())],
            HttpMethod.Post,
            JsonRequest.Create(request.Body),
            JsonResponse.Create<TasksStoriesResponse1>(),
            CreateStoryForTaskError.Response,
            AuthScheme.Any(_auth.PersonalAccessToken, _auth.Oauth2),
            requestOptions,
            cancellationToken);

    /// <summary>
    /// Delete a story
    /// </summary>
    /// <param name="request">The operation's inputs</param>
    /// <param name="requestOptions">Per-request options, such as an overriding log level for this call</param>
    /// <param name="cancellationToken">Cancellation token</param>
    /// <returns>A <see cref="Task{TResult}"/> of <see cref="StoriesResponse2"/> instance.</returns>
    /// <exception cref="ApiException{TError}"> of <see cref="DeleteStoryError"/> when the server returns an error response.</exception>
    /// <remarks>
    /// Deletes a story. A user can only delete stories they have created.
    /// <para>
    /// Returns an empty data record.
    /// </para>
    /// </remarks>
    public Task<StoriesResponse2> DeleteStory(DeleteStoryRequest request,
        RequestOptions? requestOptions = null,
        CancellationToken cancellationToken = default) =>
        _rawClient.Execute(
            _server.Default("/stories/{story_gid}"),
            [new TemplateParam("story_gid", request.StoryGid)],
            [
                new Param("opt_pretty", request.OptPretty),
                new Param("opt_fields", request.OptFields, SerializationFormat.Csv),
            ],
            [new HeaderParam("Idempotency-Key", Guid.NewGuid())],
            HttpMethod.Delete,
            EmptyBody.Instance,
            JsonResponse.Create<StoriesResponse2>(),
            DeleteStoryError.Response,
            AuthScheme.Any(_auth.PersonalAccessToken, _auth.Oauth2),
            requestOptions,
            cancellationToken);

    /// <summary>
    /// Get stories from a task
    /// </summary>
    /// <param name="request">The operation's inputs</param>
    /// <param name="requestOptions">Per-request options, such as an overriding log level for this call</param>
    /// <param name="cancellationToken">Cancellation token</param>
    /// <returns>A <see cref="Task{TResult}"/> of <see cref="TasksStoriesResponse"/> instance.</returns>
    /// <exception cref="ApiException{TError}"> of <see cref="GetStoriesForTaskError"/> when the server returns an error response.</exception>
    /// <remarks>
    /// Returns the compact records for all stories on the task.
    /// </remarks>
    public Task<TasksStoriesResponse> GetStoriesForTask(GetStoriesForTaskRequest request,
        RequestOptions? requestOptions = null,
        CancellationToken cancellationToken = default) =>
        _rawClient.Execute(
            _server.Default("/tasks/{task_gid}/stories"),
            [new TemplateParam("task_gid", request.TaskGid)],
            [
                new Param("opt_pretty", request.OptPretty),
                new Param("opt_fields", request.OptFields, SerializationFormat.Csv),
                new Param("limit", request.Limit),
                new Param("offset", request.Offset),
            ],
            [],
            HttpMethod.Get,
            EmptyBody.Instance,
            JsonResponse.Create<TasksStoriesResponse>(),
            GetStoriesForTaskError.Response,
            AuthScheme.Any(_auth.PersonalAccessToken, _auth.Oauth2),
            requestOptions,
            cancellationToken);

    /// <summary>
    /// Get a story
    /// </summary>
    /// <param name="request">The operation's inputs</param>
    /// <param name="requestOptions">Per-request options, such as an overriding log level for this call</param>
    /// <param name="cancellationToken">Cancellation token</param>
    /// <returns>A <see cref="Task{TResult}"/> of <see cref="StoriesResponse"/> instance.</returns>
    /// <exception cref="ApiException{TError}"> of <see cref="GetStoryError"/> when the server returns an error response.</exception>
    /// <remarks>
    /// Returns the full record for a single story.
    /// </remarks>
    public Task<StoriesResponse> GetStory(GetStoryRequest request,
        RequestOptions? requestOptions = null,
        CancellationToken cancellationToken = default) =>
        _rawClient.Execute(
            _server.Default("/stories/{story_gid}"),
            [new TemplateParam("story_gid", request.StoryGid)],
            [
                new Param("opt_pretty", request.OptPretty),
                new Param("opt_fields", request.OptFields, SerializationFormat.Csv),
                new Param("limit", request.Limit),
                new Param("offset", request.Offset),
            ],
            [],
            HttpMethod.Get,
            EmptyBody.Instance,
            JsonResponse.Create<StoriesResponse>(),
            GetStoryError.Response,
            AuthScheme.Any(_auth.PersonalAccessToken, _auth.Oauth2),
            requestOptions,
            cancellationToken);

    /// <summary>
    /// Update a story
    /// </summary>
    /// <param name="request">The operation's inputs</param>
    /// <param name="requestOptions">Per-request options, such as an overriding log level for this call</param>
    /// <param name="cancellationToken">Cancellation token</param>
    /// <returns>A <see cref="Task{TResult}"/> of <see cref="StoriesResponse"/> instance.</returns>
    /// <exception cref="ApiException{TError}"> of <see cref="UpdateStoryError"/> when the server returns an error response.</exception>
    /// <remarks>
    /// Updates the story and returns the full record for the updated story. Only comment stories can have their text updated, and only comment stories and attachment stories can be pinned. Only one of <c>text</c> and <c>html_text</c> can be specified.
    /// </remarks>
    public Task<StoriesResponse> UpdateStory(UpdateStoryRequest request,
        RequestOptions? requestOptions = null,
        CancellationToken cancellationToken = default) =>
        _rawClient.Execute(
            _server.Default("/stories/{story_gid}"),
            [new TemplateParam("story_gid", request.StoryGid)],
            [
                new Param("opt_pretty", request.OptPretty),
                new Param("opt_fields", request.OptFields, SerializationFormat.Csv),
            ],
            [new HeaderParam("Idempotency-Key", Guid.NewGuid())],
            HttpMethod.Put,
            JsonRequest.Create(request.Body),
            JsonResponse.Create<StoriesResponse>(),
            UpdateStoryError.Response,
            AuthScheme.Any(_auth.PersonalAccessToken, _auth.Oauth2),
            requestOptions,
            cancellationToken);
}
